export async function decode(blob){const ac=new AudioContext();try{return await ac.decodeAudioData(await blob.arrayBuffer());}finally{await ac.close();}}
export async function wav16k(buffer){const ac=new OfflineAudioContext(1,Math.ceil(buffer.duration*16000),16000),src=ac.createBufferSource();src.buffer=buffer;src.connect(ac.destination);src.start();const b=await ac.startRendering(),data=b.getChannelData(0),out=new ArrayBuffer(44+data.length*2),v=new DataView(out);const str=(o,t)=>[...t].forEach((c,i)=>v.setUint8(o+i,c.charCodeAt(0)));str(0,'RIFF');v.setUint32(4,36+data.length*2,true);str(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,16000,true);v.setUint32(28,32000,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,data.length*2,true);data.forEach((x,i)=>v.setInt16(44+i*2,Math.max(-1,Math.min(1,x))*32767,true));return new Blob([out],{type:'audio/wav'});}
export async function base64(blob){const bytes=new Uint8Array(await blob.arrayBuffer());let text='';for(let i=0;i<bytes.length;i+=8192)text+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(text);}
export function unbase64(data,mime){const text=atob(data),bytes=Uint8Array.from(text,c=>c.charCodeAt(0));return new Blob([bytes],{type:mime});}
export function effect(ac,dest,event,when){if(!Number.isFinite(when)||!Number.isFinite(event.gain)||event.gain<=0)return;const noisy=/swish|whoosh|paper|chalk|swipe|whip|scratch|shutter|clap|rocket|pageflip/.test(event.name),low=/thud|boom|impact|kick|stamp|step|heart/.test(event.name),long=/rise|riser|rocket|tada|magic/.test(event.name),duration=long?.9:noisy?.28:.16,gain=ac.createGain();gain.connect(dest);gain.gain.setValueAtTime(.0001,when);gain.gain.exponentialRampToValueAtTime(Math.min(1,event.gain)*.17,when+.01);gain.gain.exponentialRampToValueAtTime(.0001,when+duration);const pitch=Math.max(.2,Math.min(4,event.pitch||1));let source;if(noisy){const b=ac.createBuffer(1,Math.ceil(ac.sampleRate*duration),ac.sampleRate),a=b.getChannelData(0);let seed=12345;for(let i=0;i<a.length;i++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;a[i]=seed/2147483648-1;}source=ac.createBufferSource();source.buffer=b;const filter=ac.createBiquadFilter();filter.type='lowpass';filter.frequency.value=2000*pitch;source.connect(filter);filter.connect(gain);}else{source=ac.createOscillator();source.type=/buzzer|glitch|blip/.test(event.name)?'square':'sine';const f=(low?100:/ding|coin|sparkle|notify/.test(event.name)?1000:450)*pitch;source.frequency.setValueAtTime(f,when);source.frequency.exponentialRampToValueAtTime(long?f*1.8:Math.max(35,f*.45),when+duration);source.connect(gain);}source.start(when);source.stop(when+duration);}
